function calculateTaskMinutes(count) {
  let total = 0;
  for (let counter = 1; counter <= count; counter += 1) {
    total += counter * 2;
  }
  return total;
}

function calculateUsage(count, fee) {
  let total = 0;
  for (let turn = 1; turn <= count; turn += 1) {
    total += fee;
  }
  return total;
}

function sumEvenRange(start, end) {
  let total = 0;
  for (let number = start; number <= end; number += 1) {
    if (number % 2 === 0) total += number;
  }
  return total;
}
